      cursor: pointer;
    }

    .apple-pay-button:hover {
      opacity: 0.9;
    }

    /* Ha nem támogatott Apple Pay, fallback gomb */
    .card-button {
      background: #007aff;
      color: white;
      border: none;
      padding: 16px;
      border-radius: 8px;
      width: 100%;
      font-size: 16px;
      font-weight: 600;
      cursor: pointer;
      display: none;
    }
  </style>
