<body>
  <div class="product-card">
    <h2>Prémium csomag</h2>
    <p>Hozzáférés minden funkcióhoz egy évig</p>
    <div class="price">14 990 Ft</div>

    <!-- NATÍV APPLE PAY GOMB (csak Safari-ban látható) -->
    <button class="apple-pay-button" id="applePayBtn"></button>

    <!-- FALLBACK GOMB (ha nincs Apple Pay) -->
    <button class="card-button" id="cardBtn">
      Fizetés bankkártyával
    </button>
  </div>

  <script>
    const price = 14990;
    const currency = 'HUF';

    // Ellenőrizzük, hogy elérhető-e Apple Pay
    if (window.ApplePaySession && ApplePaySession.canMakePayments()) {
      document.getElementById('applePayBtn').style.display = 'block';
      document.getElementById('cardBtn').style.display = 'none';

      document.getElementById('applePayBtn').addEventListener('click', startApplePay);
    } else {
      // Ha nincs Apple Pay, fallback gomb jelenik meg
      document.getElementById('applePayBtn').style.display = 'none';
      document.getElementById('cardBtn').style.display = 'block';
      document.getElementById('cardBtn').addEventListener('click', startCardPayment);
    }

    function startApplePay() {
      // Apple Pay fizetési kérelem létrehozása
      const request = {
        countryCode: 'HU',
        currencyCode: currency,
        supportedNetworks: ['visa', 'masterCard', 'amex'],
        merchantCapabilities: ['supports3DS'],
        total: {
          label: 'Prémium csomag',
          amount: price.toString()
        }
      };

      const session = new ApplePaySession(3, request);

      // Kereskedő validáció (backend végzi)
      session.onvalidatemerchant = async (event) => {
        const response = await fetch('/validate-merchant', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ validationURL: event.validationURL })
        });
        const merchantSession = await response.json();
        session.completeMerchantValidation(merchantSession);
      };

      // Fizetés jóváhagyva
      session.onpaymentauthorized = async (event) => {
        const payment = event.payment;

        // Backend feldolgozza + Coinbase-szel konvertál
        const result = await fetch('/process-payment', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ 
            payment: payment,
            amount: price,
            currency: currency
          })
        });

        const data = await result.json();

        if (data.success) {
          session.completePayment(ApplePaySession.STATUS_SUCCESS);
          window.location.href = '/success';
        } else {
          session.completePayment(ApplePaySession.STATUS_FAILURE);
        }
      };

      session.begin();
    }

    function startCardPayment() {
      // Klasszikus kártyás fizetés Coinbase Commerce-szel
      window.location.href = '/checkout';
    }
  </script>
</body>
</html>




 Backend (Node.js / Express + Coinbase)

javascript
const express = require('express');
const axios = require('axios');
const app = express();

