const COINBASE_API_KEY = 'YOUR_API_KEY';
const APPLE_MERCHANT_ID = 'merchant.com.yourcompany';
const APPLE_CERT_PATH = './apple-pay-cert.pem'; // Apple Pay tanúsítvány

// Apple Pay merchant validáció
app.post('/validate-merchant', async (req, res) => {
  const { validationURL } = req.body;

  // Apple szervereivel kommunikálunk (SSL tanúsítvánnyal)
  const merchantSession = await axios.post(validationURL, {
    merchantIdentifier: APPLE_MERCHANT_ID,
    displayName: 'YourStore',
    initiative: 'web',
    initiativeContext: 'yourstore.com'
  }, {
    httpsAgent: new https.Agent({
      cert: fs.readFileSync(APPLE_CERT_PATH),
      key: fs.readFileSync('./apple-pay-key.pem')
    })
  });

  res.json(merchantSession.data);
});

// Fizetés feldolgozása
app.post('/process-payment', async (req, res) => {
  const { payment, amount, currency } = req.body;

  // 1. Apple Pay token -> Coinbase Onramp
  const coinbaseOrder = await axios.post(
    'https://api.cdp.coinbase.com/onramp/v2/orders',
    {
      amount: { value: amount.toString(), currency: currency },
      crypto: 'USDC',
      payment_method: 'APPLE_PAY',
      payment_token: payment.token.paymentData
    },
    {
      headers: {
        'Authorization': `Bearer ${COINBASE_API_KEY}`,
        'Content-Type': 'application/json'
      }
    }
  );

  // 2. Ha sikeres, kriptó automatikusan beérkezik
  if (coinbaseOrder.data.status === 'completed') {
    res.json({ success: true, orderId: coinbaseOrder.data.id });
  } else {
    res.json({ success: false });
  }
});

app.listen(3000, () => console.log('Server running on port 3000'));




